    "approvalContent": "我科在例行设备维护检查中发现，现有多台麻醉机的流量传感器存在以下问题：\n    1.测量数据漂移明显，与标准值偏差超过±10%\n    2.部分传感器出现零点校准失败报警\n    3.已影响潮气量等关键参数的监测准确性\n    经检测，主要原因为：现有传感器已连续使用超过2年（标准使用寿命1年）\n    现申请更换麻醉机流量传感器4个，恳请优先审批处理。",
