    "approvalStatus": "申请通过",
    "approvalDate": "",
    "approvalContent": "维修申请：\n我科彩色多普勒超声诊断仪近期出现严重的图像伪影及扫描断层现象，经初步排查确认为ACQ前端通道板和PRC电源分配板故障。该故障直接导致图像采集失真，清晰度无法满足临床诊断要求，存在极大的漏诊、误诊风险。为保障超声检查结果的精准性，现申请紧急采购并更换该配件，以恢复设备正常诊疗功能。\n\n2. 超声科（PRC电源分配板）\n维修申请：\n因超声设备近期频繁出现自动重启及供电不稳现象，经技术检测判定为PRC电源分配板老化故障。频繁断电不仅损坏系统硬盘及核心硬件，更直接导致诊疗工作中途被迫中断，存在安全隐患。为确保设备电力供应稳定及医疗安全，现申请对PRC电源分配板进行更换维修。\n\n3. 麻醉手术科（显示器维修）\n维修申请：\n手术室监护系统/工作站显示器目前出现黑屏、图像闪烁及触控失灵等异常情况，严重影响术中对患者生命体征参数的实时监测。作为手术室关键监测环节，显示器故障将直接威胁围术期安全，现申请对该显示设备进行加急维修或部件更换，以确保手术工作的顺利开展。\n\n4. 内镜室（显示器维修）\n维修申请：\n内镜系统显示器目前存在显示异常及色彩偏差，高分辨率画面无法稳定输出，导致医生在行内镜下诊疗及手术操作时观察受限，难以精准识别病灶。为规避手术风险、确保内镜操作的精细度与安全性，现申请尽快对该显示系统进行专业维修，以解决视觉障碍问题。",
    "approvedDate": "",
    "projectName": "显示器维修",
    "preApprovalPrintDate": "",
